import java.util.*;

public class Main {
    // Implicit treap over characters
    static class Node {
        char c;
        int pr, sz;
        Node l, r;
        Node(char c, int pr) {
            this.c = c;
            this.pr = pr;
            this.sz = 1;
        }
    }

    static final Random rnd = new Random(1);

    static int size(Node t) {
        return t == null ? 0 : t.sz;
    }

    static void upd(Node t) {
        if (t != null) t.sz = 1 + size(t.l) + size(t.r);
    }

    static Node[] split(Node t, int k) { // first k chars, rest
        if (t == null) return new Node[]{null, null};
        if (size(t.l) >= k) {
            Node[] sp = split(t.l, k);
            t.l = sp[1];
            upd(t);
            return new Node[]{sp[0], t};
        } else {
            Node[] sp = split(t.r, k - size(t.l) - 1);
            t.r = sp[0];
            upd(t);
            return new Node[]{t, sp[1]};
        }
    }

    static Node merge(Node a, Node b) {
        if (a == null) return b;
        if (b == null) return a;
        if (a.pr > b.pr) {
            a.r = merge(a.r, b);
            upd(a);
            return a;
        } else {
            b.l = merge(a, b.l);
            upd(b);
            return b;
        }
    }

    static Node build(String s) {
        Node root = null;
        for (int i = 0; i < s.length(); i++) {
            root = merge(root, new Node(s.charAt(i), rnd.nextInt()));
        }
        return root;
    }

    static void collect(Node t, StringBuilder sb) {
        if (t == null) return;
        collect(t.l, sb);
        sb.append(t.c);
        collect(t.r, sb);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null || first.isEmpty()) return;

        // Assumed standard format:
        // n
        // n lines of initial text
        // m
        // m commands
        //
        // Commands supported:
        // L / LEFT       : move cursor left
        // R / RIGHT      : move cursor right
        // H / HOME       : move cursor to beginning
        // E / END        : move cursor to end
        // B / BACKSPACE  : delete char before cursor
        // D / DELETE     : delete char at cursor
        // P <text>       : paste/insert text at cursor
        // C k            : cut next k characters to clipboard
        // V              : paste clipboard at cursor
        //
        // Newlines in initial text are preserved.

        int n = Integer.parseInt(first.trim());
        StringBuilder initial = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            if (line == null) line = "";
            initial.append(line);
            if (i + 1 < n) initial.append('\n');
        }

        int m = Integer.parseInt(br.readLine().trim());

        Node root = build(initial.toString());
        Node clipboard = null;
        int cursor = 0;

        for (int i = 0; i < m; i++) {
            String cmd = br.readLine();
            if (cmd == null) cmd = "";
            if (cmd.equals("L") || cmd.equals("LEFT")) {
                if (cursor > 0) cursor--;
            } else if (cmd.equals("R") || cmd.equals("RIGHT")) {
                if (cursor < size(root)) cursor++;
            } else if (cmd.equals("H") || cmd.equals("HOME")) {
                cursor = 0;
            } else if (cmd.equals("E") || cmd.equals("END")) {
                cursor = size(root);
            } else if (cmd.equals("B") || cmd.equals("BACKSPACE")) {
                if (cursor > 0) {
                    Node[] a = split(root, cursor - 1);
                    Node[] b = split(a[1], 1);
                    root = merge(a[0], b[1]);
                    cursor--;
                }
            } else if (cmd.equals("D") || cmd.equals("DELETE")) {
                if (cursor < size(root)) {
                    Node[] a = split(root, cursor);
                    Node[] b = split(a[1], 1);
                    root = merge(a[0], b[1]);
                }
            } else if (cmd.equals("V") || cmd.equals("PASTE")) {
                if (clipboard != null) {
                    StringBuilder sb = new StringBuilder();
                    collect(clipboard, sb);
                    Node ins = build(sb.toString());
                    Node[] a = split(root, cursor);
                    root = merge(merge(a[0], ins), a[1]);
                    cursor += sb.length();
                }
            } else if (cmd.startsWith("P ")) {
                String text = cmd.substring(2);
                Node ins = build(text);
                Node[] a = split(root, cursor);
                root = merge(merge(a[0], ins), a[1]);
                cursor += text.length();
            } else if (cmd.startsWith("C ")) {
                int k = Integer.parseInt(cmd.substring(2).trim());
                Node[] a = split(root, cursor);
                Node[] b = split(a[1], k);
                root = merge(a[0], b[1]);

                StringBuilder sb = new StringBuilder();
                collect(b[0], sb);
                clipboard = build(sb.toString());
            }
        }

        StringBuilder ans = new StringBuilder();
        collect(root, ans);
        System.out.print(ans.toString());
    }
