int crow = 0, ccol = 0;
char killbuf[MAXLEN*10];
int killlen = 0;

void ensure_line(int r) {
    while (nlines <= r) {
        lines[nlines] = malloc(1);
        lines[nlines][0] = '\0';
        nlines++;
    }
}

int linelen(int r) { return strlen(lines[r]); }

void insert_char(char c) {
    int len = linelen(crow);
    char *s = malloc(len + 2);
    strncpy(s, lines[crow], ccol);
    s[ccol] = c;
    strcpy(s + ccol + 1, lines[crow] + ccol);
    free(lines[crow]);
    lines[crow] = s;
    ccol++;
}

int main() {
    // Read initial text lines until "---" or similar separator, then commands
    // Actually need to figure out input format - let me just process commands
    // Assuming input is just commands, starting with empty buffer

    ensure_line(0);

    char line[MAXLEN];
    while (fgets(line, sizeof(line), stdin)) {
        int len = strlen(line);
        if (len > 0 && line[len-1] == '\n') line[--len] = '\0';

        if (strcmp(line, "C-f") == 0) {
            if (ccol < linelen(crow)) ccol++;
            else if (crow < nlines-1) { crow++; ccol = 0; }
        } else if (strcmp(line, "C-b") == 0) {
            if (ccol > 0) ccol--;
            else if (crow > 0) { crow--; ccol = linelen(crow); }
        } else if (strcmp(line, "C-n") == 0) {
            if (crow < nlines-1) { crow++; if (ccol > linelen(crow)) ccol = linelen(crow); }
        } else if (strcmp(line, "C-p") == 0) {
            if (crow > 0) { crow--; if (ccol > linelen(crow)) ccol = linelen(crow); }
        } else if (strcmp(line, "C-a") == 0) { ccol = 0; }
        else if (strcmp(line, "C-e") == 0) { ccol = linelen(crow); }
        else if (strcmp(line, "C-d") == 0) {
            int ll = linelen(crow);
            if (ccol < ll) { memmove(lines[crow]+ccol, lines[crow]+ccol+1, ll-ccol); }
            else if (crow < nlines-1) { /* merge lines */
                char *ns = malloc(ll + linelen(crow+1) + 1);
                strcpy(ns, lines[crow]); strcat(ns, lines[crow+1]);
                free(lines[crow]); free(lines[crow+1]);
                lines[crow] = ns;
                memmove(lines+crow+1, lines+crow+2, (nlines-crow-2)*sizeof(char*));
                nlines--;
            }
        } else if (strcmp(line, "C-k") == 0) {
            int ll = linelen(crow);
            if (ccol < ll) { killlen = ll-ccol; strncpy(killbuf, lines[crow]+ccol, killlen); killbuf[killlen]='\0'; lines[crow][ccol]='\0'; }
            else if (crow < nlines-1) { killbuf[0]='\n'; killbuf[1]='\0'; killlen=1; char*ns=malloc(linelen(crow)+linelen(crow+1)+1); strcpy(ns,lines[crow]); strcat(ns,lines[crow+1]); free(lines[crow]); free(lines[crow+1]); lines[crow]=ns; memmove(lines+crow+1,lines+crow+2,(nlines-crow-2)*sizeof(char*)); nlines--; }
        } else if (strcmp(line, "C-y") == 0) {
            for (int i = 0; i < killlen; i++) insert_char(killbuf[i]);
        } else if (line[0] == '\0') { /* newline - split */
            // print command?
        } else { /* treat as character to insert */
            insert_char(line[0]);
        }
    }
    for (int i = 0; i < nlines; i++) printf("%s\n", lines[i]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
   Emacs-like editor simulation.

   Supported commands:
   - h : move cursor left
   - l : move cursor right
   - k : move cursor up
   - j : move cursor down
   - x : delete character at cursor
   - d : cut current line
   - p : paste last cut line before current line
   - P : paste last cut line after current line

   Input format assumed:
   n
   <n lines of initial text>
   m
   <command string>

   The cursor starts at the beginning of the first line.
*/

typedef struct {
    char *s;
    int len;
    int cap;
} Line;

static void line_init(Line *ln, const char *src) {
    ln->len = (int)strlen(src);
    ln->cap = ln->len + 1;
    ln->s = (char *)malloc(ln->cap);
    memcpy(ln->s, src, ln->len + 1);
}

static void line_free(Line *ln) {
    free(ln->s);
    ln->s = NULL;
    ln->len = ln->cap = 0;
}

static void line_delete_char(Line *ln, int pos) {
    if (pos < 0 || pos >= ln->len) return;
    memmove(ln->s + pos, ln->s + pos + 1, ln->len - pos);
    ln->len--;
}

static char *read_line_dynamic(void) {
    int cap = 128, len = 0, c;
    char *buf = (char *)malloc(cap);
    while ((c = getchar()) != EOF && c != '\n') {
        if (len + 1 >= cap) {
            cap <<= 1;
            buf = (char *)realloc(buf, cap);
        }
        buf[len++] = (char)c;
    }
    buf[len] = '\0';
    return buf;
}

int main(void) {
    int n, m;
    if (scanf("%d", &n) != 1) return 0;
    getchar(); // consume newline

    int lines_cap = (n > 1 ? n : 1) + 100;
    int lines_cnt = n;
    Line *lines = (Line *)malloc(sizeof(Line) * lines_cap);

    for (int i = 0; i < n; i++) {
        char *tmp = read_line_dynamic();
        line_init(&lines[i], tmp);
        free(tmp);
    }

    if (scanf("%d", &m) != 1) return 0;
    getchar(); // consume newline
    char *cmd = read_line_dynamic();

    if (lines_cnt == 0) {
        lines_cnt = 1;
        line_init(&lines[0], "");
    }

    int row = 0, col = 0;
    char *clipboard = NULL;

    for (int i = 0; i < m && cmd[i]; i++) {
        char c = cmd[i];

        if (c == 'h') {
            if (col > 0) col--;
            else if (row > 0) {
                row--;
                col = lines[row].len;
            }
        } else if (c == 'l') {
            if (col < lines[row].len) col++;
            else if (row + 1 < lines_cnt) {
                row++;
                col = 0;
            }
        } else if (c == 'k') {
            if (row > 0) {
                row--;
                if (col > lines[row].len) col = lines[row].len;
            }
        } else if (c == 'j') {
            if (row + 1 < lines_cnt) {
                row++;
                if (col > lines[row].len) col = lines[row].len;
            }
        } else if (c == 'x') {
            line_delete_char(&lines[row], col);
            if (col > lines[row].len) col = lines[row].len;
        } else if (c == 'd') {
            free(clipboard);
            clipboard = (char *)malloc(lines[row].len + 1);
            memcpy(clipboard, lines[row].s, lines[row].len + 1);

            line_free(&lines[row]);
            for (int j = row; j + 1 < lines_cnt; j++) lines[j] = lines[j + 1];
            lines_cnt--;

            if (lines_cnt == 0) {
                lines_cnt = 1;
                line_init(&lines[0], "");
                row = 0;
                col = 0;
            } else {
                if (row >= lines_cnt) row = lines_cnt - 1;
                if (col > lines[row].len) col = lines[row].len;
            }
        } else if (c == 'p' || c == 'P') {
            if (!clipboard) continue;
            if (lines_cnt + 1 >= lines_cap) {
                lines_cap <<= 1;
                lines = (Line *)realloc(lines, sizeof(Line) * lines_cap);
            }

            int ins = (c == 'p' ? row : row + 1);
            if (ins < 0) ins = 0;
            if (ins > lines_cnt) ins = lines_cnt;

            for (int j = lines_cnt; j > ins; j--) lines[j] = lines[j - 1];
            line_init(&lines[ins], clipboard);
            lines_cnt++;

            if (c == 'p') row = ins;
            if (col > lines[row].len) col = lines[row].len;
        }
    }

    for (int i = 0; i < lines_cnt; i++) {
        puts(lines[i].s);
        line_free(&lines[i]);
    }

    free(lines);
    free(clipboard);
    free(cmd);
    return 0;
}
